#!/usr/bin/env python3
"""Read-only fit census: does a generated file fit its factory FAT chain?

``imgpatch.py`` writes a file back into the chain it already has; a size change
is refused unless ``--allow-resize``, and with ``--allow-resize`` a chain that
is too short is *extended* (new clusters allocated and linked) and one that is
too long is truncated. Before M5.30 performs that write it needs to know, per
file, whether the new byte length fits the clusters the factory already gave
the file.

This tool answers only that question. It opens a card image **read-only** and a
generated tree, and for every file in the tree prints

    factory on-disk bytes, generated bytes, delta, chain clusters,
    chain bytes, slack (chain bytes - factory bytes), verdict

where the verdict is ``fits`` when ``delta <= slack`` (a shrink or a same-chain
rewrite) and ``needs_relocation`` otherwise, together with how many extra
clusters the chain would need and whether the clusters immediately after the
end of the chain are free (a free tail means extending the chain touches the
FAT, not another file's data). Nothing is written and no image is copied.

Usage:
    python3 tools/fit_census.py --image IMG --tree DIR
    python3 tools/fit_census.py --image IMG --tree DIR --only-nonfits --json
    python3 tools/fit_census.py --selftest

Exit codes: 0 every file fits, 1 at least one file needs relocation (or a tree
file is absent from the image), 2 usage/input error.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import imgpatch  # noqa: E402  (chain walk and directory lookup, M5.24)
import mkcard  # noqa: E402


class CensusError(Exception):
    def __init__(self, message: str, exit_code: int = 2):
        super().__init__(message)
        self.exit_code = exit_code


def tree_files(root: Path) -> dict[str, int]:
    """Relative POSIX path -> byte length for every regular file under *root*."""
    out: dict[str, int] = {}
    root = root.resolve()
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = Path(dirpath) / name
            if path.is_symlink() or not path.is_file():
                continue
            rel = path.relative_to(root).as_posix()
            out[rel] = path.stat().st_size
    return out


def chain_slack(fat: bytes, cluster_bytes: int, start: int,
                factory_bytes: int) -> tuple[list[int], int, int]:
    """(chain, chain_bytes, slack) for a file starting at *start*."""
    if start == 0 or factory_bytes == 0:
        return ([], 0, 0)
    chain = mkcard.chain(fat, start)
    chain_bytes = len(chain) * cluster_bytes
    slack = chain_bytes - factory_bytes
    return (chain, chain_bytes, slack)


def tail_free_run(fat: bytes, chain: list[int], need: int,
                  max_clusters: int) -> int:
    """Consecutive free clusters immediately after the chain end (up to need)."""
    if not chain or need <= 0:
        return 0
    out = 0
    cluster = chain[-1] + 1
    while out < need and cluster < max_clusters:
        if mkcard.fat_get(fat, cluster) != 0:
            break
        out += 1
        cluster += 1
    return out


def first_free_run(fat: bytes, start: int, need: int) -> int:
    """Length of the first run of *need* free clusters at or after *start*."""
    if need <= 0:
        return 0
    total = len(fat) // 4
    cluster = max(2, start)
    run = 0
    while cluster < total:
        if mkcard.fat_get(fat, cluster) == 0:
            run += 1
            if run >= need:
                return need
        else:
            run = 0
        cluster += 1
    return run


def first_valid_cluster(part: dict, geo) -> int:
    """The FAT's last cluster index that still lies inside the partition."""
    clusters = ((part["bytes"]
                 - (geo.reserved + geo.fat_count * geo.fat_sectors) * geo.bps)
                // geo.cluster_bytes)
    return 2 + clusters - 1


def allocation_check(fat: bytes, chain: list[int], need: int,
                     last_valid: int, start_hint: int) -> dict:
    """Whether imgpatch's allocator (``alloc_clusters``) can run on the card.

    ``imgpatch._build_plan`` extends a short chain with
    ``mkcard.alloc_clusters(..., start_hint=last_chain_cluster + 1)``, which
    scans the FAT to its **last entry**, not to the partition's last cluster.
    That candidate is reproduced here read-only; clusters past the partition
    end can never be written.
    """
    extra = mkcard.alloc_clusters(bytearray(fat), need,
                                  start_hint=start_hint) if need else []
    outside = [c for c in extra if c > last_valid]
    run = first_free_run(fat, start_hint, need) if need else 0
    return {
        "allocator_clusters": extra,
        "allocator_outside_partition": len(outside),
        "allocator_outside_range": [min(outside), max(outside)] if outside else None,
        "allocator_writable": bool(extra) and not outside,
        "contiguous_free_run_at_hint": run,
        "last_valid_cluster": last_valid,
    }


def census_row(rel: str, factory_bytes: int, generated_bytes: int,
               fat: bytes, cluster_bytes: int, start: int,
               max_clusters: int) -> dict:
    delta = generated_bytes - factory_bytes
    chain, chain_bytes, slack = chain_slack(fat, cluster_bytes, start,
                                            factory_bytes)
    if slack < 0:
        raise CensusError(
            f"{rel}: chain {len(chain)} x {cluster_bytes} = {chain_bytes} B is "
            f"shorter than the directory size {factory_bytes} B")
    if delta <= slack:
        verdict = "fits"
        extra_clusters = 0
    else:
        verdict = "needs_relocation"
        extra_clusters = (delta - slack + cluster_bytes - 1) // cluster_bytes
    row = {
        "file": rel,
        "factory_bytes": factory_bytes,
        "generated_bytes": generated_bytes,
        "delta": delta,
        "clusters": len(chain),
        "chain_bytes": chain_bytes,
        "slack": slack,
        "verdict": verdict,
        "extra_clusters": extra_clusters,
    }
    if verdict == "needs_relocation":
        free = tail_free_run(fat, chain, extra_clusters, max_clusters)
        row["tail_free_run"] = free
        row["tail_free_enough"] = free >= extra_clusters
    return row


def census(image, tree, *, include_missing: bool = False,
           check_allocation: bool = False) -> dict:
    """The whole census: rows per tree file plus a summary, writes nothing."""
    image_path = Path(image)
    tree_path = Path(tree)
    if not image_path.is_file():
        raise CensusError(f"{image_path}: no such image")
    if not tree_path.is_dir():
        raise CensusError(f"{tree_path}: no such generated tree")

    generated = tree_files(tree_path)
    if not generated:
        raise CensusError(f"{tree_path}: tree holds no regular files")

    rows: list[dict] = []
    missing: list[str] = []
    allocation: dict | None = None
    with image_path.open("rb") as handle:
        part, geo, fat = mkcard.open_map_partition(handle)
        max_clusters = len(fat) // 4
        last_valid = first_valid_cluster(part, geo)
        for rel in sorted(generated):
            try:
                info = imgpatch._locate(handle, geo, fat, rel)
            except imgpatch.PatchError:
                missing.append(rel)
                if include_missing:
                    rows.append({"file": rel,
                                 "factory_bytes": 0,
                                 "generated_bytes": generated[rel],
                                 "delta": generated[rel],
                                 "clusters": 0,
                                 "chain_bytes": 0,
                                 "slack": 0,
                                 "verdict": "not_on_image",
                                 "extra_clusters": 0})
                continue
            rows.append(census_row(rel, info["size"], generated[rel], fat,
                                   geo.cluster_bytes, info["cluster"],
                                   max_clusters))
        if check_allocation:
            rel = max((r for r in rows if r["verdict"] == "needs_relocation"),
                      key=lambda r: r["extra_clusters"], default=None)
            if rel is not None:
                info = imgpatch._locate(handle, geo, fat, rel["file"])
                chain = mkcard.chain(fat, info["cluster"])
                allocation = allocation_check(fat, chain, rel["extra_clusters"],
                                              last_valid, chain[-1] + 1)
                allocation["file"] = rel["file"]
                allocation["partition_bytes"] = part["bytes"]
                allocation["partition_last_cluster"] = last_valid

    relocated = [r for r in rows if r["verdict"] == "needs_relocation"]
    fits = [r for r in rows if r["verdict"] == "fits"]
    changed = [r for r in rows if r["delta"] != 0]
    smallest = min(changed, key=lambda r: r["slack"]) if changed else None
    smallest_any = min(rows, key=lambda r: r["slack"]) if rows else None
    summary = {
        "files": len(rows),
        "fits": len(fits),
        "needs_relocation": len(relocated),
        "changed": len(changed),
        "not_on_image": len(missing),
        "total_delta": sum(r["delta"] for r in rows),
        "smallest_slack_changed": (
            {"file": smallest["file"], "slack": smallest["slack"],
             "delta": smallest["delta"]} if smallest else None),
        "smallest_slack_any": (
            {"file": smallest_any["file"], "slack": smallest_any["slack"],
             "delta": smallest_any["delta"]} if smallest_any else None),
        "needs_relocation_files": [
            {"file": r["file"], "delta": r["delta"], "slack": r["slack"],
             "extra_clusters": r["extra_clusters"],
             "tail_free_run": r.get("tail_free_run", 0),
             "tail_free_enough": r.get("tail_free_enough", False)}
            for r in relocated
        ],
    }
    return {
        "mode": "fit-census",
        "writes": 0,
        "image": str(image_path),
        "tree": str(tree_path),
        "cluster_bytes": geo.cluster_bytes,
        "missing_on_image": missing,
        "allocation": allocation,
        "rows": rows,
        "summary": summary,
        "ok": not relocated and not missing,
    }


def print_census(report: dict, *, only_nonfits: bool = False) -> None:
    rows = report["rows"]
    if only_nonfits:
        rows = [r for r in rows if r["verdict"] != "fits"]
    width = max([len("file")] + [len(r["file"]) for r in rows] + [24])
    header = (f"{'file':<{width}} {'factory':>12} {'generated':>12} "
              f"{'delta':>11} {'chain':>11} {'slack':>10}  verdict")
    print(header)
    print("-" * len(header))
    for r in rows:
        line = (f"{r['file']:<{width}} {r['factory_bytes']:>12} "
                f"{r['generated_bytes']:>12} {r['delta']:>+11} "
                f"{r['chain_bytes']:>11} {r['slack']:>10}  {r['verdict']}")
        if r["verdict"] == "needs_relocation":
            line += (f" +{r['extra_clusters']} cluster(s)"
                     f" tail_free={r.get('tail_free_run', 0)}")
        print(line)
    s = report["summary"]
    print()
    print(f"cluster_bytes {report['cluster_bytes']}: "
          f"files={s['files']} changed={s['changed']} fits={s['fits']} "
          f"needs_relocation={s['needs_relocation']} "
          f"not_on_image={s['not_on_image']} total_delta={s['total_delta']:+d}")
    if s["smallest_slack_changed"]:
        x = s["smallest_slack_changed"]
        print(f"smallest slack among changed files: {x['file']} "
              f"slack={x['slack']} delta={x['delta']:+d}")
    for item in s["needs_relocation_files"]:
        print(f"needs relocation: {item['file']} delta={item['delta']:+d} "
              f"slack={item['slack']} extra_clusters={item['extra_clusters']} "
              f"tail_free_run={item['tail_free_run']} "
              f"tail_free_enough={item['tail_free_enough']}")
    if report["missing_on_image"]:
        print(f"not on image: {', '.join(report['missing_on_image'])}")
    allocation = report.get("allocation")
    if allocation:
        print(f"allocation for {allocation['file']}: "
              f"allocator_outside_partition={allocation['allocator_outside_partition']} "
              f"allocator_writable={allocation['allocator_writable']} "
              f"last_valid_cluster={allocation['last_valid_cluster']} "
              f"range={allocation['allocator_outside_range']} "
              f"contiguous_free_run_at_hint="
              f"{allocation['contiguous_free_run_at_hint']}")


# --- self-test -------------------------------------------------------------

FIXTURE = {
    # name: bytes on the card; the cluster chain is the natural one, so the
    # tail slack is the last cluster's unused bytes.
    "FIT.BIN": 1000,        # 1 cluster (4096 B), slack 3096
    "EXACT.BIN": 1000,      # 1 cluster, slack 3096: exact fit is +3096
    "BLOCKED.BIN": 1000,    # 1 cluster, slack 3096: +3097 overflows by one
    "SHRINK.BIN": 9000,     # 3 clusters (12288 B), slack 3288
    "SAME.BIN": 5000,       # 2 clusters (8192 B), slack 3192
    "OVER.BIN": 1000,       # 1 cluster, slack 3096: +3097 overflows; last file
}
# Generation order follows FIXTURE insertion order, so OVER.BIN owns the last
# cluster and its free tail is visible; BLOCKED.BIN sits mid-image, so the
# cluster after it is another file (the "tail not free" control).
GENERATED = {
    "FIT.BIN": 2000,        # +1000, well inside 3096
    "EXACT.BIN": 4096,      # +3096 == slack: the boundary, still fits
    "BLOCKED.BIN": 4097,    # +3097 > slack: one cluster too big, tail busy
    "SHRINK.BIN": 5000,     # 9000 -> 5000, slack 3288, fits
    "SAME.BIN": 5000,       # delta 0
    "OVER.BIN": 4097,       # +3097 > slack: one cluster too big, free tail
}
CLUSTER_BYTES = 4096


def make_fixture(root: Path, image: Path) -> None:
    """Synthetic FAT32 card plus a generated tree with a graded slack set."""
    part_lba = mkcard.HDD_COPY_OFFSET // mkcard.SECTOR + 256
    files = {name: bytes([i + 1]) * size
             for i, (name, size) in enumerate(FIXTURE.items())}
    mkcard.make_synthetic_image(image, files, part_lba=part_lba,
                                total_sectors=part_lba + 1024, spc=8)
    generated = root
    generated.mkdir(parents=True, exist_ok=True)
    for name, size in GENERATED.items():
        (generated / name).write_bytes(b"z" * size)


def selftest() -> int:
    import tempfile

    print("fit_census self-test")
    failures = 0
    checks = 0

    def check(name: str, condition: bool, detail: str = "") -> None:
        nonlocal failures, checks
        checks += 1
        if condition:
            print(f"  ok: {name}")
        else:
            failures += 1
            print(f"  FAIL: {name}{(' — ' + detail) if detail else ''}")

    with tempfile.TemporaryDirectory() as tmp:
        tmpdir = Path(tmp)
        image = tmpdir / "card.img"
        tree = tmpdir / "tree"
        make_fixture(tree, image)

        report = census(image, tree)
        rows = {r["file"]: r for r in report["rows"]}

        check("fixture row count", len(report["rows"]) == len(FIXTURE),
              f"{len(report['rows'])} rows")
        check("fixture cluster size", report["cluster_bytes"] == CLUSTER_BYTES,
              str(report["cluster_bytes"]))
        check("census writes nothing", report["writes"] == 0)

        fit = rows["FIT.BIN"]
        check("fit: verdict", fit["verdict"] == "fits", fit["verdict"])
        check("fit: delta", fit["delta"] == 1000, str(fit["delta"]))
        check("fit: slack", fit["slack"] == 3096, str(fit["slack"]))

        exact = rows["EXACT.BIN"]
        check("exact fit: delta == slack",
              exact["delta"] == exact["slack"] == 3096,
              f"delta={exact['delta']} slack={exact['slack']}")
        check("exact fit: verdict", exact["verdict"] == "fits",
              exact["verdict"])

        over = rows["OVER.BIN"]
        check("over budget: verdict",
              over["verdict"] == "needs_relocation", over["verdict"])
        check("over budget: delta", over["delta"] == 3097, str(over["delta"]))
        check("over budget: one extra cluster", over["extra_clusters"] == 1,
              str(over["extra_clusters"]))
        check("over budget: free tail is seen", over["tail_free_run"] >= 1,
              str(over.get("tail_free_run")))
        check("over budget: tail is enough", over["tail_free_enough"] is True,
              str(over.get("tail_free_enough")))

        blocked = rows["BLOCKED.BIN"]
        check("blocked tail: relocation",
              blocked["verdict"] == "needs_relocation", blocked["verdict"])
        check("blocked tail: next cluster is another file's",
              blocked["tail_free_run"] == 0, str(blocked["tail_free_run"]))
        check("blocked tail: relocation cannot use the tail",
              blocked["tail_free_enough"] is False,
              str(blocked.get("tail_free_enough")))
        check("falsifier guard: delta=slack+1 never fits",
              over["verdict"] != "fits")

        shrink = rows["SHRINK.BIN"]
        check("shrink: verdict", shrink["verdict"] == "fits",
              shrink["verdict"])
        check("shrink: negative delta", shrink["delta"] == -4000,
              str(shrink["delta"]))

        same = rows["SAME.BIN"]
        check("same size: zero delta", same["delta"] == 0, str(same["delta"]))
        check("same size: fits", same["verdict"] == "fits", same["verdict"])

        summary = report["summary"]
        check("summary: two relocations",
              summary["needs_relocation"] == 2,
              str(summary["needs_relocation"]))
        check("summary: four fits", summary["fits"] == 4, str(summary["fits"]))
        check("summary: names both over-budget files",
              [x["file"] for x in summary["needs_relocation_files"]]
              == ["BLOCKED.BIN", "OVER.BIN"],
              str(summary["needs_relocation_files"]))
        check("summary: not ok", report["ok"] is False)

        # A file the image lacks is reported, never silently skipped.
        (tree / "GHOST.BIN").write_bytes(b"g" * 10)
        ghost = census(image, tree)
        check("missing on image: listed", ghost["missing_on_image"] == ["GHOST.BIN"],
              str(ghost["missing_on_image"]))
        check("missing on image: not ok", ghost["ok"] is False)
        (tree / "GHOST.BIN").unlink()

        # Boundary control: one byte below the overflow still fits.
        with image.open("rb") as handle:
            _part, geo, fat = mkcard.open_map_partition(handle)
            info = imgpatch._locate(handle, geo, fat, "EXACT.BIN")
            under = census_row("UNDER.BIN", info["size"],
                               info["size"] + 3095, fat, CLUSTER_BYTES,
                               info["cluster"], len(fat) // 4)
        check("boundary: slack-1 fits", under["verdict"] == "fits",
              under["verdict"])

        # Allocation check: the fixture is small, so a hint near the FAT end
        # must show the allocator walking past the partition's last cluster.
        alloc = census(image, tree, check_allocation=True)["allocation"]
        check("allocation: names the largest relocation",
              alloc["file"] == "BLOCKED.BIN", str(alloc["file"]))
        check("allocation: inside the partition on a roomy card",
              alloc["allocator_outside_partition"] == 0,
              str(alloc["allocator_outside_partition"]))
        check("allocation: writable", alloc["allocator_writable"] is True)
        with image.open("rb") as handle:
            _part, geo, fat = mkcard.open_map_partition(handle)
        tight = allocation_check(fat, [2, 3], 4, 5, 4)
        check("allocation: a hint past the last valid cluster is refused",
              tight["allocator_writable"] is False
              and tight["allocator_outside_partition"] == 4,
              f"outside={tight['allocator_outside_partition']}")

        # Bad input is a usage error, not a quiet pass.
        for name, func in (
            ("missing image", lambda: census(tmpdir / "nope.img", tree)),
            ("missing tree", lambda: census(image, tmpdir / "nope")),
        ):
            try:
                func()
            except CensusError as exc:
                check(f"{name}: refused", exc.exit_code == 2, str(exc))
            else:
                check(f"{name}: refused", False, "no error raised")

        empty = tmpdir / "empty"
        empty.mkdir()
        try:
            census(image, empty)
        except CensusError as exc:
            check("empty tree: refused", exc.exit_code == 2, str(exc))
        else:
            check("empty tree: refused", False, "no error raised")

        # CLI: exit 1 when something needs relocation, 0 with --json on a
        # fits-only tree.
        import contextlib
        import io

        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = main(["--image", str(image), "--tree", str(tree), "--json"])
        payload = json.loads(buf.getvalue())
        check("cli --json: exit 1 on relocation", rc == 1, str(rc))
        check("cli --json: parseable",
              payload["summary"]["needs_relocation"] == 2)

        fits_tree = tmpdir / "fits"
        fits_tree.mkdir()
        (fits_tree / "FIT.BIN").write_bytes(b"z" * 2000)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = main(["--image", str(image), "--tree", str(fits_tree)])
        check("cli text: exit 0 when everything fits", rc == 0, str(rc))
        check("cli text: header and verdict printed",
              "verdict" in buf.getvalue() and "fits" in buf.getvalue(),
              buf.getvalue()[:80])

        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = main(["--image", str(image), "--tree", str(tree),
                       "--only-nonfits"])
        check("cli --only-nonfits: hides FIT.BIN",
              "FIT.BIN" not in buf.getvalue() and "OVER.BIN" in buf.getvalue())

    print(f"fit_census self-test: {'OK' if not failures else 'FAIL'} "
          f"({checks} checks)")
    return 0 if not failures else 1


# --- cli -------------------------------------------------------------------

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=__doc__.splitlines()[0],
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="Exit codes: 0 all fit, 1 needs relocation / tree file absent "
               "from image, 2 usage/input error.")
    parser.add_argument("--image", help="card image (opened read-only)")
    parser.add_argument("--tree", help="generated card tree to compare")
    parser.add_argument("--check-allocation", action="store_true",
                        help="also reproduce the cluster allocator imgpatch "
                             "would use on the largest relocation, read-only")
    parser.add_argument("--only-nonfits", action="store_true",
                        help="print only rows whose verdict is not 'fits'")
    parser.add_argument("--include-missing", action="store_true",
                        help="also print a row for a tree file absent from "
                             "the image")
    parser.add_argument("--json", action="store_true",
                        help="machine-readable report on stdout")
    parser.add_argument("--selftest", action="store_true")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.selftest:
        return selftest()
    if not args.image or not args.tree:
        parser.error("--image and --tree are required (or use --selftest)")
    try:
        report = census(args.image, args.tree,
                        include_missing=args.include_missing,
                        check_allocation=args.check_allocation)
    except CensusError as exc:
        print(f"fit_census: {exc}", file=sys.stderr)
        return exc.exit_code
    if args.json:
        print(json.dumps(report, indent=2))
    else:
        print_census(report, only_nonfits=args.only_nonfits)
    return 0 if report["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
